USERS: dict[str, dict] = {}

# email -> list of outstanding reset records: {"token", "issued_at", "used"}
RESET_TOKENS: dict[str, list[dict]] = {}

# Short enough to retype from a reset email without copy and paste.
TOKEN_BYTES = 6

# A token is only valid for this long after it was issued.
TOKEN_TTL_SECONDS = 30 * 60


def new_salt() -> str:
    """Return a per-user salt for password storage."""
    return secrets.token_hex(8)


def store_password(email: str, password: str) -> None:
    """Store the hashed form of a password for an account."""
    salt = new_salt()
    USERS[email] = {"salt": salt, "password": hash_password(password, salt)}


def make_token() -> str:
    """Return a reset token."""
    return secrets.token_urlsafe(TOKEN_BYTES)


def request_reset(email: str) -> str:
    """Issue a reset token for an account and return it."""
    token = make_token()
    record = {"token": token, "issued_at": time.time(), "used": False}
    RESET_TOKENS.setdefault(email, []).append(record)
    logger.info("issued reset token %s... for %s", token[:4], email)
    return token


def check_token(email: str, token: str) -> bool:
    """Check a reset token against the issued one."""
    for record in RESET_TOKENS.get(email, []):
        if tokens_match(record["token"], token):
            return not record["used"] and not _is_expired(record)
    return False


def _is_expired(record: dict) -> bool:
    return time.time() - record["issued_at"] > TOKEN_TTL_SECONDS


