    """Complete a password reset.

    Verifies that the token was issued for the account, has not already been
    used, and has not expired. On success the new password is stored and every
    other outstanding token for the account is invalidated so a stale or
    leaked token can no longer be redeemed.
    """
    records = RESET_TOKENS.get(email, [])
    matched = None
    for record in records:
        if tokens_match(record["token"], token):
            matched = record
            break

    if matched is None or matched["used"] or _is_expired(matched):
        return False

    store_password(email, new_password)

    for record in records:
        record["used"] = True

    return True

